				_B135 = _T134 == 1 && minF(inOpen[i-3], inClose[i-3]) > maxF(inOpen[i-4], inClose[i-4]) && inHigh[i-2] > inHigh[i-3] && inLow[i-2] > inLow[i-3] && inHigh[i-1] > inHigh[i-2] && inLow[i-1] > inLow[i-2] && inClose[i] < inOpen[i-3] && inClose[i] > inClose[i-4]
